        [Test]
        public async Task TestSkippedTokensTriviaTokenDeleteRewriter()
        {
            var oldNode = GenerateSkippedTokensTrivia();
            var rewriter = new TokenDeleteRewriter();
            var newNode = rewriter.Visit(oldNode);

            if (!oldNode.IsMissing)
            {
                await Assert.That(newNode).IsNotEqualTo(oldNode);
            }

            await Assert.That(newNode).IsNotNull();
            await Assert.That(newNode.IsMissing).IsTrue().Because("No tokens => missing");
        }

